orders = frappe.db.get_all("Book Order",{"docstatus":1},pluck="name")
book_qty = {}

for order in orders:
    doc = frappe.get_doc("Book Order",order)
    for i in doc.items:
        if i.book in book_qty:
            book_qty[i.book] = book_qty[i.book] + i.quantity
        else:
            book_qty[i.book] = i.quantity

for book, qty in book_qty.items():
    frappe.db.set_value("Book",book,"ordered_qty",qty)
